SELECT s.vendor_name
FROM poz_suppliers s
WHERE EXISTS (
    SELECT 1 FROM ap_invoices_all i
    WHERE i.vendor_id = s.vendor_id
);

SELECT s.vendor_name
FROM poz_suppliers s
WHERE NOT EXISTS (
    SELECT 1 FROM ap_invoices_all i
    WHERE i.vendor_id = s.vendor_id
);

-- DANGEROUS: one NULL invoice_id here silently returns ZERO rows
